window.products.push({"id":143203,"name":"OEM Refrigerator Door Bin Basket Compatible With Samsung Model Numbers RF28HFEDBSG, RF28HFEDBSG/AA, RF28HFEDBSR, RF28HFEDBSR/AA","category":"homeandappliances","retail price":121.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71AsCpS02iL._AC_SL1500_.jpg","description":"Up for Sale are Samsung Refrigerator Basket Assemblies! This bin is for the RIGHT door (when looking into the refrigerator) and for the 1st, 2nd, or 3rd bin from the top. These bins were originally shipped with the following Samsung Refrigerators: RF28HFEDBSG, RF28HFEDBSG/AA, RF28HFEDBSR, RF28HFEDBSR/AA These items are NEW and are true Samsung parts! Refrigerator doors can have multiple bins, if the bin you are trying to replace does not look like the one in the picture or if you unsure if this is the correct bin or if you don't See your model number -- Please send us a message so we can help you to select the correct bin. We are happy to help!","images":["https://m.media-amazon.com/images/I/71AsCpS02iL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"GenuineOEMSamsung","source_asin":"B083K3LYQ5","category_path":"Home & Appliances"},"sku":"BM-143203","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B083K3LYQ5","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B083K3LYQ5","price_pending":true,"merchant_ready":false});
